mockup.css:
.mock-section-overflow-rail { background: #f6f4ed; color: #17150f; font-family: var(--f-sans);
  display: flex; flex-direction: column; gap: 2.8cqw; padding: 5cqw 0 5cqw 6cqw; }
.mock-section-overflow-rail .head { display: flex; align-items: baseline; gap: 2cqw; padding-right: 6cqw; }
.mock-section-overflow-rail h4 { margin: 0; font-family: var(--f-serif); font-size: 3.4cqw; }
.mock-section-overflow-rail .head span { margin-left: auto; font-family: var(--f-mono); font-size: 1.15cqw;
  letter-spacing: .16em; text-transform: uppercase; opacity: .45; }
.mock-section-overflow-rail .track { display: flex; gap: 2.4cqw; }
.mock-section-overflow-rail .it { flex: 0 0 26cqw; display: flex; flex-direction: column; gap: 1.2cqw; }
.mock-section-overflow-rail .it i { display: block; block-size: 15cqw; }
.mock-section-overflow-rail .it b { font-weight: 600; font-size: 1.7cqw; }
.mock-section-overflow-rail .it span { font-size: 1.3cqw; opacity: .58; }
.mock-section-overflow-rail .progress { margin-right: 6cqw; block-size: 2px; background: rgba(23,21,15,.16);
  position: relative; }
.mock-section-overflow-rail .progress::after { content: ""; position: absolute; inset-block: 0; left: 0;
  inline-size: 34%; background: #17150f; }
